package io.lumine.mythic.lib.skill;
import io.lumine.mythic.lib.skill.handler.SkillHandler; import io.lumine.mythic.lib.skill.result.SkillResult; import io.lumine.mythic.lib.skill.trigger.TriggerType;
public class SimpleSkill extends Skill { public static final SimpleSkill EMPTY=new SimpleSkill(); public SimpleSkill(){super();} public SimpleSkill(SkillHandler<?> h){super(h);} public SimpleSkill(TriggerType t,SkillHandler<?> h){super(t,h);} public boolean getResult(SkillMetadata m){SkillHandler<?> h=getHandler();return h==null||h.getResult(m).isSuccessful(m);} @SuppressWarnings({"rawtypes","unchecked"}) public void whenCast(SkillMetadata m){SkillHandler h=getHandler();if(h!=null){SkillResult r=(SkillResult)h.getResult(m);h.whenCast(r,m);}} public double getParameter(String id){return super.getParameter(id);} }
